#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <algorithm>
#include <array>
#include <cassert>
#include <random>
#include <iostream>
class Bag{
    std::array<int,3> values_{{0,1,2}};
    std::size_t next_=3;
    std::mt19937 rng_;
public:
    explicit Bag(unsigned seed):rng_(seed){}
    int draw(){
        if(next_==3){values_={{0,1,2}};std::shuffle(values_.begin(),values_.end(),rng_);next_=0;}
        return values_[next_++];
    }
};
int main(){
    Bag bag(42);
    for(int batch=0;batch<1000;++batch){
        std::array<int,3> counts{{0,0,0}};
        for(int i=0;i<3;++i){int x=bag.draw();assert(x>=0 && x<3);++counts[x];}
        assert(counts[0]==1 && counts[1]==1 && counts[2]==1);
    }
    Bag a(7),b(7);
    for(int i=0;i<100;++i)assert(a.draw()==b.draw());
    std::cout<<"bag invariant tests passed\n";
}
